{!! '<?php' !!}
/**
 * Generated by the control panel — do not edit by hand.
 *
 * Turns a one-time token minted by the panel into a signed-in Adminer session.
 *
 * The panel cannot log a user in directly: it runs as its own account, in its
 * own Laravel application, and Adminer only trusts a PHP session written on
 * this site. So the panel drops a short-lived file that only this site's user
 * can read, and hands the browser a token naming it. Nothing sensitive travels
 * in the URL, and nothing is left on disk once it has been used.
 *
 * Deliberately dependency-free: it is a plain PHP file in a public web root,
 * so the less it does the smaller it is to get wrong.
 */

declare(strict_types=1);

const TOKEN_DIRECTORY = {!! var_export($tokenDirectory, true) !!};

/* The server keys index.php accepts, with the Adminer driver each runs. */
const PANEL_SERVERS = {!! var_export($drivers, true) !!};

/**
 * One answer for every failure. Distinguishing "no such token" from "expired"
 * from "malformed" tells someone guessing tokens which of their guesses was
 * closer, and tells a legitimate user nothing they can act on.
 */
function deny(): never
{
    http_response_code(403);
    header('Content-Type: text/plain; charset=utf-8');
    exit("This sign-in link is not valid. Open Adminer from the control panel again.\n");
}

$token = isset($_GET['token']) && is_string($_GET['token']) ? $_GET['token'] : '';

/* No token at all is someone who typed the address: the ordinary login form. */
if ($token === '') {
    header('Location: /');
    exit;
}

/*
 * Checked before the token is used to build a path. The token names a file, so
 * without this a crafted value walks out of the directory.
 */
if (preg_match('/^[A-Za-z0-9]{64}$/', $token) !== 1) {
    deny();
}

$file = TOKEN_DIRECTORY.'/'.$token.'.json';

$raw = @file_get_contents($file);

/*
 * Consumed before it is trusted, and a failure to consume it is fatal. If the
 * file cannot be removed the token stays usable for the rest of its life, and
 * a link that has already been used would work again for anyone who has it.
 */
$consumed = is_string($raw) && @unlink($file);

if (! $consumed) {
    deny();
}

$payload = json_decode($raw, true);

if (! is_array($payload)
    || ! isset($payload['server'], $payload['username'], $payload['password'], $payload['expires_at'])
    || ! is_string($payload['server'])
    || ! is_string($payload['username'])
    || ! is_string($payload['password'])
    || ! isset(PANEL_SERVERS[$payload['server']])
) {
    deny();
}

if ((int) $payload['expires_at'] < time()) {
    deny();
}

$driver = PANEL_SERVERS[$payload['server']];
$server = $payload['server'];
$username = $payload['username'];
$database = isset($payload['database']) && is_string($payload['database']) ? $payload['database'] : '';

/*
 * Adminer's own session: its name, and the cookie it sets for a page served
 * from the site root — `/`, which is where this redirects. `secure` follows the
 * request, as Adminer's does.
 */
session_name('adminer_sid');
session_set_cookie_params([
    'lifetime' => 0,
    'path' => '/',
    'secure' => ! empty($_SERVER['HTTPS']) && strcasecmp((string) $_SERVER['HTTPS'], 'off') !== 0,
    'httponly' => true,
    'samesite' => 'Lax',
]);
session_start();

/* A session id that predates the login must not survive it. */
session_regenerate_id(true);

/*
 * Exactly what Adminer's login form stores (auth.inc.php): the password under
 * driver / server / user, and the database as one this user has opened. A
 * plain string is the form Adminer itself keeps when the browser has no
 * `adminer_key` cookie yet, and it reads both forms.
 */
$_SESSION['pwds'][$driver][$server][$username] = $payload['password'];
$_SESSION['db'][$driver][$server][$username][$database] = true;

/*
 * Adminer's CSRF seed, set by its own login form too. Without it Adminer reads
 * the session as stale and answers every failure — a database that is down, a
 * password changed since — with "Session expired", which sends the user
 * looking in the wrong place.
 */
$_SESSION['token'] = random_int(1, 1000000);

session_write_close();

$location = '/?'.http_build_query(array_filter([
    $driver => $server,
    'username' => $username,
    'db' => $database,
], fn ($value): bool => $value !== ''));

header('Location: '.$location);
exit;
